const db = require('../db');

// Adds the incoming quantity to one product's stock row.
async function applyRestock({ warehouseId, sku, quantity }) {
  const rows = await db.query(
    'SELECT product_id FROM products WHERE warehouse_id = $1 AND sku = $2',
    [warehouseId, sku],
  );
  const product = rows[0];
  if (!product) return null;
  await db.query(
    'UPDATE stock_levels SET on_hand = on_hand + $2 WHERE product_id = $1',
    [product.product_id, quantity],
  );
  return product.product_id;
}

module.exports = { applyRestock };
